import XCTest
@testable import RemoteTerminal

final class OpenSSHKeyCodecTests: XCTestCase {
    // Standard unencrypted ed25519 generated by `ssh-keygen -t ed25519 -N ""`
    let ed25519Private = """
    -----BEGIN OPENSSH PRIVATE KEY-----
    b3BlbnNzaC1rZXktdjEAAAAABG5vbmUAAAAEbm9uZQAAAAAAAAABAAAAMwAAAAtzc2gtZW
    QyNTUxOQAAACADJ+t+t8TwcqVXwMUqWy2lXt5AFMfYavzdurEkQORj/QAAAJjGjEjAxoxI
    wAAAAAtzc2gtZWQyNTUxOQAAACADJ+t+t8TwcqVXwMUqWy2lXt5AFMfYavzdurEkQORj/Q
    AAAECgkFa7TfA1Poo1y+5+FmljoI9fKYGcmrVoJwOM/YvAAAMn6363xPBypVfAxSpbLaVe
    3kAUx9hq/N26sSRA5GP9AAAADnJhbWVzaEBtYWMubGFuAQIDBAUGBw==
    -----END OPENSSH PRIVATE KEY-----
    """

    let ed25519Public = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAMn6363xPBypVfAxSpbLaVe3kAUx9hq/N26sSRA5GP9 ramesh@mac.lan"

    func testParseEd25519() throws {
        let parsed = try OpenSSHKeyCodec.parsePrivateKey(ed25519Private)
        XCTAssertEqual(parsed.kind, .ed25519)
        XCTAssertEqual(parsed.comment, "ramesh@mac.lan")

        // Encode the parsed NIOSSHPrivateKey's public key and ensure it matches the .pub file
        let encodedPub = OpenSSHKeyCodec.publicKeyString(parsed.privateKey.publicKey, comment: parsed.comment)
        XCTAssertEqual(encodedPub, ed25519Public)

        // Verify fingerprint matches `ssh-keygen -lf`
        let fingerprint = OpenSSHKeyCodec.fingerprint(parsed.privateKey.publicKey)
        XCTAssertEqual(fingerprint, "SHA256:UftCCMvLAPCSPC2BZa8jovTlvXRHs+JmLo+n6UOffNM")
    }

    func testParseRejectsEncryptedKey() {
        let encrypted = """
        -----BEGIN OPENSSH PRIVATE KEY-----
        b3BlbnNzaC1rZXktdjEAAAAACmFlczI1Ni1jdHIAAAAGYmNyeXB0AAAAGAAAABCe01XSIV
        E1q6wlVWrK4AuYAAAAGAAAAAEAAAAzAAAAC3NzaC1lZDI1NTE5AAAAIFufnpeJ4NdswvKz
        Ij0IWnzNZP/ymDXNbR8FSYLE2MCEAAAAoN2Cl8L85XMn79w0jeKP8c5x5poWe3p5RASKBA
        X8sI8yXRIzem9H3KIAUh3ogXOCCHwBDmxVzZVVq14BHQiKs02PjEv1VpHmbry0KW57a/Qx
        f9d22QdWIMXJNjFZ2GwAWCq7nCRMCwQXUJduNu5kYLt1eFnFTtRbgIPMn1mDyKEV30tTC5
        5Mzh/VRxSecBHh1LaVA38/9sjCU1WDU3U2vXA=
        -----END OPENSSH PRIVATE KEY-----
        """
        XCTAssertThrowsError(try OpenSSHKeyCodec.parsePrivateKey(encrypted)) { error in
            guard let e = error as? OpenSSHKeyError, case .encryptedKeyNotSupported(let cipher) = e else {
                XCTFail("Expected encryptedKeyNotSupported, got \(error)")
                return
            }
            XCTAssertEqual(cipher, "aes256-ctr")
        }
    }

    func testParseRejectsRSA() {
        let rsa = "-----BEGIN RSA PRIVATE KEY-----\nMIIE..."
        XCTAssertThrowsError(try OpenSSHKeyCodec.parsePrivateKey(rsa)) { error in
            guard let e = error as? OpenSSHKeyError, case .unsupportedKeyType = e else { XCTFail(); return }
        }
    }
}
